using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Diagnostics;using System.Threading;using System.Threading.Tasks;using System.Windows.Forms;
namespace Musikbox {
 public static class VideoAudioImport {
 public static Uri Validate(string text){Uri uri;if(!Uri.TryCreate(text,UriKind.Absolute,out uri)||(uri.Scheme!="http"&&uri.Scheme!="https")||String.IsNullOrWhiteSpace(uri.Host)||uri.UserInfo.Length>0)throw new ArgumentException("Bitte einen gültigen HTTP- oder HTTPS-Videolink ohne eingebettete Zugangsdaten eingeben.");return uri;}
 public static string Download(string url,string format,int quality,string parent,string exe,string ffmpeg,string jsRuntime,Action check,Action<string> progress){Validate(url);if(!new[]{"best","mp3","m4a","flac","wav","opus","vorbis"}.Contains(format))throw new ArgumentException("Nicht unterstütztes Audioformat.");if(quality<0||quality>9)throw new ArgumentException("Ungültige Qualität.");if(!File.Exists(exe))throw new FileNotFoundException("yt-dlp fehlt im portablen Paket.",exe);string stage=BatchFiles.Stage(parent);try{var info=new ProcessStartInfo{FileName=Path.GetFullPath(exe),WorkingDirectory=stage,UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};string[] args={"--ignore-config","--no-plugin-dirs","--no-playlist","--no-overwrites","--no-progress","--newline","--progress","--progress-delta","0.5","--socket-timeout","20","--retries","3","-f","bestaudio/best","-x","--audio-format",format,"--audio-quality",quality.ToString(),"--ffmpeg-location",Path.GetDirectoryName(Path.GetFullPath(ffmpeg)),"--windows-filenames","-o",Path.Combine(stage,"%(title).160B [%(id)s].%(ext)s")};foreach(var arg in args)info.ArgumentList.Add(arg);if(File.Exists(jsRuntime)){info.ArgumentList.Add("--js-runtimes");info.ArgumentList.Add("deno:"+Path.GetFullPath(jsRuntime));}info.ArgumentList.Add("--");info.ArgumentList.Add(url);using(var process=new Process{StartInfo=info}){var log=new System.Text.StringBuilder();object gate=new object();DataReceivedEventHandler receive=(s,e)=>{if(e.Data==null)return;lock(gate){if(log.Length>64000)log.Remove(0,32000);log.AppendLine(e.Data);}if(progress!=null)progress(e.Data);};process.OutputDataReceived+=receive;process.ErrorDataReceived+=receive;check();process.Start();process.BeginOutputReadLine();process.BeginErrorReadLine();var timer=Stopwatch.StartNew();try{while(!process.WaitForExit(100)){check();if(timer.Elapsed.TotalMinutes>60)throw new TimeoutException("Video-Audio-Import hat das Zeitlimit überschritten.");}process.WaitForExit();check();if(process.ExitCode!=0)throw new IOException("Video-Audio-Import fehlgeschlagen. Quelle möglicherweise nicht unterstützt, gesperrt oder nicht erreichbar.\r\n"+log);}catch{try{process.Kill(true);process.WaitForExit(5000);}catch{}throw;}}var files=Directory.GetFiles(stage).Where(f=>Ffmpeg.Extensions.Contains(Path.GetExtension(f).ToLowerInvariant())&&!MediaProbe57.Extensions.Contains(Path.GetExtension(f).ToLowerInvariant())).ToArray();if(files.Length==0)throw new IOException("Die Quelle lieferte keine unterstützte Audiodatei.");foreach(string file in files){check();if(MediaMetadata.Read(file).Duration<=0)throw new IOException("Die heruntergeladene Audiodatei ist nicht lesbar.");}check();return BatchFiles.Commit(stage,"Video-Audio-Import");}catch{BatchFiles.Cleanup(stage);throw;}}
 }
 public partial class Controller {
 void OpenVideoAudioImport(){var panel=ModulePage("Video-Audio-Import","Audio aus berechtigt nutzbaren Videolinks übernehmen. Plattformbeschränkungen werden nicht umgangen.");var bar=ModuleButtons(panel);var link=new StudioTextBox{Width=420};var format=Choice("Original","MP3","M4A","FLAC","WAV","OPUS","OGG");var quality=Choice("Mittel (V4)","Standard (V2)","Hoch (V1)","Extrem (V0)");quality.SelectedIndex=1;quality.Enabled=false;format.SelectedIndexChanged+=(s,e)=>quality.Enabled=(string)format.SelectedItem=="MP3";var destination=new StudioTextBox{Width=330,ReadOnly=true,Text=StudioPreferences.Folder("Video-Audio-Import")};bar.Controls.Add(new Label{Text="Videolink",AutoSize=true});bar.Controls.Add(link);bar.Controls.Add(format);bar.Controls.Add(quality);bar.Controls.Add(MainView.StudioButton("Speicherort wählen",()=>{using(var d=new AppFolderDialog{SelectedPath=destination.Text})if(d.ShowDialog(v)==DialogResult.OK){StudioPreferences.SaveFolder("Video-Audio-Import",d.SelectedPath);destination.Text=d.SelectedPath;}}));bar.Controls.Add(destination);var surface=new StudioTextSurface{Dock=DockStyle.Fill};panel.Controls.Add(surface);surface.BringToFront();var log=surface.Content;var progress=new StudioProgressBar{Dock=DockStyle.Bottom,Height=18};panel.Controls.Add(progress);
 bar.Controls.Add(MainView.StudioButton("Audio importieren",async()=>{if(busy)return;string url=link.Text.Trim(),parent=destination.Text,type=new[]{"best","mp3","m4a","flac","wav","opus","vorbis"}[format.SelectedIndex];int level=new[]{4,2,1,0}[quality.SelectedIndex];try{VideoAudioImport.Validate(url);}catch(Exception ex){AppMessage.Show(v,ex.Message);return;}if(!Directory.Exists(parent)){AppMessage.Show(v,"Bitte Speicherort wählen.");return;}StudioPreferences.SaveFolder("Video-Audio-Import",parent);cancel=new CancellationTokenSource();var token=cancel.Token;SetBusy(true);string result=null;try{result=await Task.Run(()=>VideoAudioImport.Download(url,type,level,parent,PortablePaths.Tool(Path.Combine("yt-dlp","yt-dlp.exe")),p.FfmpegExecutable,PortablePaths.Tool(Path.Combine("yt-dlp","deno.exe")),()=>token.ThrowIfCancellationRequested(),line=>UI(()=>{if(log.IsDisposed)return;if(log.TextLength>64000)log.Clear();log.AppendText(line+"\r\n");var match=System.Text.RegularExpressions.Regex.Match(line,@"(\d+(?:\.\d+)?)%");double value;if(match.Success&&Double.TryParse(match.Groups[1].Value,System.Globalization.NumberStyles.Float,System.Globalization.CultureInfo.InvariantCulture,out value))progress.Value=Math.Max(0,Math.Min(100,(int)value));})));if(!log.IsDisposed)log.AppendText("Gespeichert: "+result+"\r\n");}catch(OperationCanceledException){if(!log.IsDisposed)log.AppendText("Abgebrochen.\r\n");}catch(Exception ex){if(!log.IsDisposed)log.AppendText(ex.Message+"\r\n");}finally{cancel.Dispose();cancel=null;SetBusy(false);}if(result!=null)ImportDropped(Directory.GetFiles(result).Where(f=>Ffmpeg.Extensions.Contains(Path.GetExtension(f).ToLowerInvariant())).ToArray(),-1,true,false);},true));bar.Controls.Add(MainView.StudioButton("Abbrechen",()=>{if(cancel!=null)cancel.Cancel();}));v.ShowModule(panel,SelectWorkingPaths);
 }
 }
